"use client";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { bankStaffLoginAreaSchema, type BankStaffLoginAreaInput } from "@/lib/validation/bankStaffLoginArea";

// Bank Staff Login Area — create/edit form, generated by RNC from the UIR.
export default function BankStaffLoginAreaForm() {
  const router = useRouter();
  const { register, handleSubmit, setValue, formState: { errors } } =
    useForm<BankStaffLoginAreaInput>({ resolver: zodResolver(bankStaffLoginAreaSchema) });

  async function onSubmit(values: BankStaffLoginAreaInput) {
    const res = await fetch("/api/bank_staff_login_areas", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(values),
    });
    if (res.ok) router.push("/bank_staff_login_areas");
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="container mx-auto max-w-xl space-y-4 py-8">
      <h1 className="text-2xl font-bold">Bank Staff Login Area</h1>
      <Button type="submit">Save</Button>
    </form>
  );
}
